import * as zlib from 'zlib';
import * as crypto from 'crypto';
import { promisify } from 'util';

const inflate = promisify(zlib.inflate);
const deflate = promisify(zlib.deflate);

interface User {
  id: string;
  username: string;
  role: 'admin' | 'manager' | 'user';
  permissions: string[];
}

interface SessionToken {
  payload: Buffer;
  signature: string;
  compressed: boolean;
  compressionRatio?: number;
}

const HMAC_SECRET = crypto.randomBytes(32);
const MAX_DECOMPRESSED_SIZE = 10 * 1024 * 1024; // 10MB limit
const MAX_COMPRESSION_RATIO = 100; // max 100:1 ratio
const MAX_COMPRESSED_INPUT = 1 * 1024 * 1024; // 1MB max compressed input
const ROLE_HIERARCHY: Record<string, number> = {
  'admin': 3,
  'manager': 2,
  'user': 1
};

function computeSignature(data: Buffer): string {
  return crypto.createHmac('sha256', HMAC_SECRET).update(data).digest('hex');
}

function verifySignature(data: Buffer, signature: string): boolean {
  const expected = computeSignature(data);
  const expectedBuf = Buffer.from(expected);
  const providedBuf = Buffer.from(signature);
  // Length check prevents timingSafeEqual from throwing on mismatched lengths.
  if (expectedBuf.length !== providedBuf.length) {
    return false;
  }
  return crypto.timingSafeEqual(expectedBuf, providedBuf);
}

async function createSessionToken(user: User): Promise<SessionToken> {
  const payload = Buffer.from(JSON.stringify({
    id: user.id,
    username: user.username,
    role: user.role,
    permissions: user.permissions,
    iat: Date.now(),
    exp: Date.now() + 3600000
  }));

  const compressed = await deflate(payload);
  const ratio = payload.length / compressed.length;

  const tokenData = compressed;
  const signature = computeSignature(tokenData);

  return {
    payload: tokenData,
    signature,
    compressed: true,
    compressionRatio: ratio
  };
}

async function validateAndDecompress(token: SessionToken): Promise<Buffer> {
  if (!token.compressed) {
    return token.payload;
  }

  // Hard limit on compressed input size
  if (token.payload.length > MAX_COMPRESSED_INPUT) {
    throw new Error('Compressed input exceeds maximum allowed size');
  }

  // Use streaming decompression with hard output limit
  const decompressed = await new Promise<Buffer>((resolve, reject) => {
    const chunks: Buffer[] = [];
    let totalSize = 0;

    const decompressor = zlib.createInflate();

    decompressor.on('data', (chunk: Buffer) => {
      totalSize += chunk.length;
      if (totalSize > MAX_DECOMPRESSED_SIZE) {
        decompressor.destroy();
        reject(new Error('Decompressed size exceeds maximum allowed'));
        return;
      }
      chunks.push(chunk);
    });

    decompressor.on('end', () => {
      resolve(Buffer.concat(chunks));
    });

    decompressor.on('error', (err) => {
      reject(new Error(`Decompression failed: ${err.message}`));
    });

    decompressor.write(token.payload);
    decompressor.end();
  });

  // Post-decompression ratio check
  const actualRatio = decompressed.length / token.payload.length;
  if (actualRatio > MAX_COMPRESSION_RATIO) {
    throw new Error('Compression ratio exceeds maximum allowed');
  }

  return decompressed;
}

async function authenticateToken(token: SessionToken): Promise<User> {
  // Verify signature first
  if (!verifySignature(token.payload, token.signature)) {
    throw new Error('Invalid token signature');
  }

  // Validate and decompress
  const rawPayload = await validateAndDecompress(token);

  const data = JSON.parse(rawPayload.toString('utf-8'));

  // Check expiration
  if (data.exp < Date.now()) {
    throw new Error('Token expired');
  }

  return {
    id: data.id,
    username: data.username,
    role: data.role,
    permissions: data.permissions
  };
}

function checkPermission(user: User, requiredRole: string, resource: string): boolean {
  const userLevel = ROLE_HIERARCHY[user.role] || 0;
  const requiredLevel = ROLE_HIERARCHY[requiredRole] || 0;

  if (userLevel < requiredLevel) {
    return false;
  }

  if (resource && !user.permissions.includes(resource) && user.role !== 'admin') {
    return false;
  }

  return true;
}

async function handleProfileUpload(token: SessionToken, profileData: Buffer): Promise<{ success: boolean; message: string }> {
  const user = await authenticateToken(token);

  if (!checkPermission(user, 'user', 'profile:write')) {
    return { success: false, message: 'Insufficient permissions' };
  }

  // Process profile data (compressed payload from client)
  const uploadToken: SessionToken = {
    payload: profileData,
    signature: computeSignature(profileData),
    compressed: true,
    compressionRatio: undefined
  };

  const decompressedProfile = await validateAndDecompress(uploadToken);

  // Store profile...
  return { success: true, message: `Profile updated (${decompressedProfile.length} bytes)` };
}

export {
  createSessionToken,
  authenticateToken,
  checkPermission,
  handleProfileUpload,
  User,
  SessionToken
};
